package dev.smpcristalix.pvpcombat.service;
import dev.smpcristalix.pvpcombat.PvPCombatPlugin;import dev.smpcristalix.pvpcombat.config.PvPCombatSettings;import org.bukkit.Material;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.Damageable;import org.bukkit.potion.*;import org.bukkit.scheduler.BukkitRunnable;import java.util.*;import java.util.concurrent.*;
/** Weapon-proc механика: меч, топор, лук и арбалет. */
public final class AbilityService{private final PvPCombatPlugin plugin;private final StatsService stats;private PvPCombatSettings settings;private final Map<UUID,Long> stunned=new ConcurrentHashMap<>();private final Map<UUID,BukkitRunnable> bleeds=new ConcurrentHashMap<>();public AbilityService(PvPCombatPlugin p,StatsService s,PvPCombatSettings c){plugin=p;stats=s;settings=c;}public void reload(PvPCombatSettings s){settings=s;}public boolean isStunned(Player p){return stunned.getOrDefault(p.getUniqueId(),0L)>System.currentTimeMillis();}public void trySword(Player a,Player v){int l=stats.profile(a.getUniqueId()).abilityLevel();if(l<=0||!roll(settings.abilityChance("sword",l)))return;startBleed(v,Math.max(1,(int)Math.round(settings.abilityDuration("sword","duration-seconds",l))));}public void tryAxe(Player a,Player v){int l=stats.profile(a.getUniqueId()).abilityLevel();if(l<=0||a.getAttackCooldown()<settings.axeMinimumCharge()||!roll(settings.abilityChance("axe",l)))return;stun(v,settings.abilityDuration("axe","stun-seconds",l));damageArmor(v,settings.abilityInt("axe","armor-durability-multiplier",l,1));}public void tryBow(Player a,Player v){int l=stats.profile(a.getUniqueId()).abilityLevel();if(l<=0||!roll(settings.abilityChance("bow",l)))return;int b=settings.abilityInt("bow","knockback-bonus-percent",l,0);v.setVelocity(v.getVelocity().multiply(1.0+b/100.0));int t=Math.max(1,(int)Math.round(settings.abilityDuration("bow","slowness-seconds",l)*20));v.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,t,0,false,true,true));}public void tryCrossbow(Player a,Player v){int l=stats.profile(a.getUniqueId()).abilityLevel();if(l<=0||!roll(settings.abilityChance("crossbow",l)))return;stun(v,settings.abilityDuration("crossbow","stun-seconds",l));damageArmor(v,settings.abilityInt("crossbow","armor-durability-multiplier",l,1));}private void startBleed(Player v,int sec){BukkitRunnable old=bleeds.remove(v.getUniqueId());if(old!=null)old.cancel();BukkitRunnable task=new BukkitRunnable(){int left=sec;public void run(){if(!v.isOnline()||v.isDead()||left--<=0){cancel();bleeds.remove(v.getUniqueId());return;}v.setHealth(Math.max(0,v.getHealth()-settings.swordBleedDamageHp()));}};bleeds.put(v.getUniqueId(),task);task.runTaskTimer(plugin,20L,20L);}private void stun(Player v,double sec){long until=System.currentTimeMillis()+Math.max(0L,(long)(sec*1000));stunned.merge(v.getUniqueId(),until,Math::max);v.setVelocity(v.getVelocity().zero());}private void damageArmor(Player v,int m){if(m<=1)return;for(ItemStack i:v.getInventory().getArmorContents()){if(i==null||i.getType()==Material.AIR)continue;if(!(i.getItemMeta() instanceof Damageable d))continue;d.setDamage(d.getDamage()+Math.max(0,m-1));i.setItemMeta(d);}}private boolean roll(double p){return ThreadLocalRandom.current().nextDouble(100)<p;}}
